args.sql:
SELECT COUNT(*) FROM (
    SELECT DISTINCT s.stellarref FROM stars s
    JOIN planets p ON p.hostlink = s.stellarref
    GROUP BY s.stellarref, s.compcount
    HAVING COUNT(p.planetref) > 1
) sub;

